type Props = {
  contentState: any;
  ricosProps: { plugins?: { type: string }[]; content?: any };
  mode: 'viewer' | 'editor';
  version: string;
  schema?: Pick<RicosSchema, 'getContent' | 'setContent'>;
  editorView?: EditorView;
};

type DevToolsMode = 'ricos' | 'prosemirror';

const DEV_TOOLS_KEY = '__RICOS_DEV_TOOLS_OPENED_ELEMENT__';
const DEV_TOOLS_DOCK_SIZE = 0.5;
const MIN_PROSEMIRROR_DOCK_SIZE = 0.15;
const MAX_DEV_TOOLS_DOCK_SIZE = 0.95;
const SHELL_TOP_ROW_HEIGHT = 40;
const PROSEMIRROR_FLOATING_CONTROLS_OFFSET = -(SHELL_TOP_ROW_HEIGHT + 32);
const RICOS_INSPECT_TRIGGER_ICON =
  'data:image/png;base64,';
const RICOS_INSPECT_BUTTON_BACKGROUND = 'rgba(137, 220, 235, .72)';
const RICOS_INSPECT_BUTTON_ACTIVE_BACKGROUND = 'rgba(137, 220, 235, .94)';
const PROSEMIRROR_TOOL_BUTTON_BACKGROUND = theme.main60;

const clampDockSize = (size: number) => Math.min(MAX_DEV_TOOLS_DOCK_SIZE, Math.max(size, 0));

const getOverlayRatio = () => SHELL_TOP_ROW_HEIGHT / window.innerHeight;

const toProseMirrorDockSize = (dockSize: number) =>
  clampDockSize(Math.max(MIN_PROSEMIRROR_DOCK_SIZE, dockSize - getOverlayRatio()));

const fromProseMirrorDockSize = (dockSize: number) => clampDockSize(dockSize + getOverlayRatio());

const getVisibleProseMirrorDockSize = (dockSize: number) =>
  fromProseMirrorDockSize(toProseMirrorDockSize(dockSize));

const getPointerClientY = (event: MouseEvent | TouchEvent) =>
  'touches' in event ? (event.touches[0]?.clientY ?? 0) : event.clientY;

const isInteractiveTarget = (target: EventTarget | null) =>
  target instanceof HTMLElement &&
  Boolean(target.closest('button, a, input, textarea, select, [role="button"]'));

const stopEventPropagation = (
  event: React.MouseEvent<HTMLDivElement> | React.TouchEvent<HTMLDivElement>
) => {
  event.stopPropagation();
};

const isEditorPluginName = (
  pluginName: EditorPluginName | undefined
): pluginName is EditorPluginName => Boolean(pluginName);

const getEditorPluginNames = (plugins?: { type: string }[]) =>
  plugins?.map(plugin => toEditorPluginName(plugin.type)).filter(isEditorPluginName) || [];

const getRicosNodeIdFromTarget = (editorView: EditorView, target: EventTarget | null) => {
  if (!(target instanceof Node) || !editorView.dom.contains(target)) {
    return undefined;
  }

  let currentTarget: Node | null = target;
  while (currentTarget && editorView.dom.contains(currentTarget)) {
    try {
      const position = editorView.posAtDOM(currentTarget, 0);
      const resolvedPosition = editorView.state.doc.resolve(position);

      for (let depth = resolvedPosition.depth; depth > 0; depth -= 1) {
        const id = resolvedPosition.node(depth).attrs?.id;
        if (typeof id === 'string' && id.length) {
          return id;
        }
      }
    } catch {}

    currentTarget = currentTarget.parentNode;
  }

  return undefined;
};

const useDockHeight = (dock: HTMLElement | null) => {
  const [dockHeight, setDockHeight] = React.useState(0);

  React.useLayoutEffect(() => {
    if (!dock) {
      setDockHeight(0);
      return;
    }

    const updateDockHeight = () => setDockHeight(dock.getBoundingClientRect().height);

    updateDockHeight();

    const resizeObserver =
      typeof ResizeObserver !== 'undefined' ? new ResizeObserver(updateDockHeight) : null;
    resizeObserver?.observe(dock);

    window.addEventListener('resize', updateDockHeight);

    return () => {
      resizeObserver?.disconnect();
      window.removeEventListener('resize', updateDockHeight);
    };
  }, [dock]);

  return dockHeight;
};

const getProseMirrorReservedHeight = (dockSize: number) =>
  getVisibleProseMirrorDockSize(dockSize) * window.innerHeight;
const getRicosReservedHeight = (dockSize: number) => clampDockSize(dockSize) * window.innerHeight;

export const RicosDevTools: React.FC<Props & { autoOpen: boolean }> = ({
  contentState,
  ricosProps,
  mode,
  version,
  autoOpen,
  schema,
  editorView,
}) => {
  if (typeof window === 'undefined') {
    return null;
  }

  const [isOpen, toggle] = useGlobalDevToolsState(autoOpen);
  const hasProseMirrorMode = mode === 'editor' && Boolean(editorView);
  const [selectedMode, setSelectedMode] = React.useState<DevToolsMode>('ricos');
  const [dockSize, setDockSize] = React.useState(DEV_TOOLS_DOCK_SIZE);
  const [proseMirrorDock, setProseMirrorDock] = React.useState<HTMLDivElement | null>(null);
  const [proseMirrorNodePickerButton, setProseMirrorNodePickerButton] =
    React.useState<HTMLButtonElement | null>(null);
  const [proseMirrorSaveSnapshotButton, setProseMirrorSaveSnapshotButton] =
    React.useState<HTMLButtonElement | null>(null);
  const proseMirrorDockHeight = useDockHeight(proseMirrorDock);
  const syncProseMirrorDockSize = React.useCallback(() => {
    if (!hasProseMirrorMode) {
      return;
    }

    setProseMirrorDevToolsSize(
      toProseMirrorDockSize(dockSize),
      getProseMirrorReservedHeight(dockSize)
    );
  }, [dockSize, hasProseMirrorMode]);

  React.useEffect(() => {
    if (selectedMode !== 'prosemirror' || !proseMirrorDockHeight) {
      return;
    }

    const nextDockSize = fromProseMirrorDockSize(proseMirrorDockHeight / window.innerHeight);
    if (Math.abs(nextDockSize - dockSize) > 0.001) {
      setDockSize(nextDockSize);
    }
  }, [proseMirrorDockHeight, selectedMode]);

  React.useEffect(() => {
    if (!isOpen || selectedMode !== 'ricos') {
      setDevToolsHtmlMarginBottomPixels();
      return;
    }

    const syncRicosDockSize = () => {
      setDevToolsHtmlMarginBottomPixels(getRicosReservedHeight(dockSize));
    };

    syncRicosDockSize();
    window.addEventListener('resize', syncRicosDockSize);

    return () => {
      window.removeEventListener('resize', syncRicosDockSize);
      setDevToolsHtmlMarginBottomPixels();
    };
  }, [dockSize, isOpen, selectedMode]);

  React.useEffect(() => {
    syncProseMirrorDockSize();
  }, [syncProseMirrorDockSize]);

  React.useEffect(() => {
    if (!hasProseMirrorMode || !isOpen || selectedMode !== 'prosemirror') {
      return;
    }

    window.addEventListener('resize', syncProseMirrorDockSize);

    return () => {
      window.removeEventListener('resize', syncProseMirrorDockSize);
    };
  }, [hasProseMirrorMode, isOpen, selectedMode, syncProseMirrorDockSize]);

  React.useEffect(() => {
    if (!hasProseMirrorMode && selectedMode === 'prosemirror') {
      setSelectedMode('ricos');
    }
  }, [hasProseMirrorMode, selectedMode]);

  React.useEffect(() => {
    let isCancelled = false;

    if (!editorView || !hasProseMirrorMode) {
      setProseMirrorFloatingControlsOffset();
      setProseMirrorFloatingControlsVisibility(true);
      setProseMirrorDock(null);
      setProseMirrorNodePickerButton(null);
      setProseMirrorSaveSnapshotButton(null);
      return;
    }

    if (isOpen && selectedMode === 'prosemirror') {
      void showStandaloneProseMirrorDevTools(
        editorView,
        toProseMirrorDockSize(dockSize),
        getProseMirrorReservedHeight(dockSize)
      ).then(elements => {
        if (!isCancelled) {
          setProseMirrorFloatingControlsOffset(PROSEMIRROR_FLOATING_CONTROLS_OFFSET);
          setProseMirrorDock(elements?.dock ?? null);
          setProseMirrorNodePickerButton(elements?.nodePickerButton ?? null);
          setProseMirrorSaveSnapshotButton(elements?.saveSnapshotButton ?? null);
          setProseMirrorFloatingControlsVisibility(false);
        }
      });
    } else {
      setProseMirrorFloatingControlsOffset();
      setProseMirrorFloatingControlsVisibility(true);
      setProseMirrorDock(null);
      setProseMirrorNodePickerButton(null);
      setProseMirrorSaveSnapshotButton(null);
      hideStandaloneProseMirrorDevTools(
        isOpen && selectedMode === 'ricos' ? getRicosReservedHeight(dockSize) : undefined
      );
    }

    return () => {
      isCancelled = true;
    };
  }, [editorView, hasProseMirrorMode, isOpen, selectedMode]);

  React.useEffect(
    () => () => {
      hideStandaloneProseMirrorDevTools();
    },
    []
  );

  return (
    <>
      <button
        onClick={toggle}
        type="button"
        style={{
          border: 'none',
          background: 'transparent',
          position: 'absolute',
          right: '0px',
          color: 'black',
          padding: '5px',
          cursor: 'pointer',
          zIndex: 1,
        }}
        className="ricos-dev-tools-button"
        tabIndex={-1}
      >
        <RcpLogo fill={hasWixInsiderOverride ? '#F63B1F' : '#231f20'} />
      </button>
      {isOpen && selectedMode === 'ricos' && (
        <RicosDevToolsDock
          contentState={contentState}
          ricosProps={ricosProps}
          close={toggle}
          mode={mode}
          version={version}
          schema={schema}
          editorView={editorView}
          hasProseMirrorMode={hasProseMirrorMode}
          dockSize={dockSize}
          onDockSizeChange={setDockSize}
          selectedMode={selectedMode}
          onModeSelect={setSelectedMode}
        />
      )}
      {isOpen && selectedMode === 'prosemirror' && hasProseMirrorMode && (
        <RicosProseMirrorOverlay
          close={toggle}
          dockSize={dockSize}
          onDockSizeChange={setDockSize}
          mode={mode}
          version={version}
          ricosProps={ricosProps}
          contentState={contentState}
          selectedMode={selectedMode}
          onModeSelect={setSelectedMode}
          proseMirrorNodePickerButton={proseMirrorNodePickerButton}
          proseMirrorSaveSnapshotButton={proseMirrorSaveSnapshotButton}
        />
      )}
    </>
  );
};

// We want all instances of this dashboard to be closed when opening current instance, so we use
// global state to track opened dashboard
const useGlobalDevToolsState = (initiallyOpen: boolean): [boolean, () => void] => {
  (window as any)[DEV_TOOLS_KEY] =
    (window as any)[DEV_TOOLS_KEY] ??
    (() => {
      const state = {
        activeDashboard: {} as object | undefined,
        subscribers: [] as (() => void)[],
        toggle: (identityObject: object) => {
          if (state.activeDashboard === identityObject) {
            state.activeDashboard = undefined;
          } else {
            state.activeDashboard = identityObject;
          }
          state.subscribers.forEach(x => x());
        },
        setActiveDashboard: (identityObject: object) => {
          state.activeDashboard = identityObject;
          state.subscribers.forEach(x => x());
        },
        subscribe: (fn: () => void) => {
          state.subscribers.push(fn);
        },
        unsubscribe: (fn: () => void) => {
          state.subscribers = state.subscribers.filter(x => x !== fn);
        },
      };
      return state;
    })();

  const [identityObject] = React.useState({});
  const [_, forceUpdate] = React.useReducer(x => x + 1, 0);

  React.useEffect(() => {
    (window as any)[DEV_TOOLS_KEY].subscribe(forceUpdate);
    if (initiallyOpen) {
      (window as any)[DEV_TOOLS_KEY].setActiveDashboard(identityObject);
    }
    return () => {
      (window as any)[DEV_TOOLS_KEY].unsubscribe(forceUpdate);
    };
  }, []);
  return [
    (window as any)[DEV_TOOLS_KEY].activeDashboard === identityObject,
    () => (window as any)[DEV_TOOLS_KEY].toggle(identityObject),
  ];
};

const RicosDevToolsDock: React.FC<
  Props & {
    close: () => void;
    hasProseMirrorMode: boolean;
    dockSize: number;
    onDockSizeChange: (size: number) => void;
    selectedMode: DevToolsMode;
    onModeSelect: (mode: DevToolsMode) => void;
  }
> = ({
  contentState,
  close,
  ricosProps,
  mode,
  version,
  schema: schemaFallback,
  editorView: editorViewFallback,
  hasProseMirrorMode,
  dockSize,
  onDockSizeChange,
  selectedMode,
  onModeSelect,
}) => {
  const [tabIndex, setTabIndex] = React.useState('state');
  const plugins = getEditorPluginNames(ricosProps.plugins);
  const schema = React.useContext(SchemaContext) ?? schemaFallback;
  const editor = React.useContext(EditorContext);
  const tiptapEditor = editor?.adapter?.tiptapEditor;
  const editorView = tiptapEditor?.view ?? editorViewFallback;
  const canInspect = mode === 'editor' && Boolean(editorView && tiptapEditor);
  const [isInspectActive, setIsInspectActive] = React.useState(false);
  const [selectedNodeId, setSelectedNodeId] = React.useState<string | undefined>(undefined);
  const hoveredNodeIdRef = React.useRef<string | undefined>(undefined);

  const clearInspectHighlight = React.useCallback(() => {
    hoveredNodeIdRef.current = undefined;
    tiptapEditor?.commands.setSpotlightList([], true);
  }, [tiptapEditor]);

  const deactivateInspectMode = React.useCallback(() => {
    setIsInspectActive(false);
    clearInspectHighlight();
  }, [clearInspectHighlight]);

  const toggleInspectMode = React.useCallback(() => {
    if (isInspectActive) {
      deactivateInspectMode();
      return;
    }

    hoveredNodeIdRef.current = undefined;
    setIsInspectActive(true);
  }, [deactivateInspectMode, isInspectActive]);

  React.useEffect(() => {
    if (canInspect) {
      return;
    }

    deactivateInspectMode();
  }, [canInspect, deactivateInspectMode]);

  React.useEffect(() => {
    if (!isInspectActive || !editorView || !tiptapEditor) {
      return;
    }

    const updateHoveredNode = (target: EventTarget | null) => {
      const nextNodeId = getRicosNodeIdFromTarget(editorView, target);

      if (hoveredNodeIdRef.current === nextNodeId) {
        return;
      }

      hoveredNodeIdRef.current = nextNodeId;
      tiptapEditor.commands.setSpotlightList(
        nextNodeId
          ? [{ type: 'range', from: nextNodeId, to: nextNodeId, highlightType: 'background' }]
          : [],
        true
      );
    };

    const handleMouseMove = (event: MouseEvent) => {
      updateHoveredNode(event.target);
    };

    const handleClick = (event: MouseEvent) => {
      const nodeId = getRicosNodeIdFromTarget(editorView, event.target);
      if (!nodeId) {
        return;
      }

      event.preventDefault();
      event.stopPropagation();
      setTabIndex(currentTabIndex =>
        currentTabIndex === 'contentEditor' ? currentTabIndex : 'state'
      );
      setSelectedNodeId(nodeId);
      deactivateInspectMode();
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') {
        event.preventDefault();
        deactivateInspectMode();
      }
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('click', handleClick, true);
    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('click', handleClick, true);
      document.removeEventListener('keydown', handleKeyDown);
      clearInspectHighlight();
    };
  }, [clearInspectHighlight, deactivateInspectMode, editorView, isInspectActive, tiptapEditor]);

  return ReactDOM.createPortal(
    <Dock
      position="bottom"
      dimMode="none"
      isVisible
      size={dockSize}
      onSizeChange={size => onDockSizeChange(clampDockSize(size))}
      zIndex={DEV_TOOLS_Z_INDEX}
      fluid
      duration={0}
    >
      <div
        data-hook={CLICK_OUTSIDE_SAFE_DATA_HOOK}
        onMouseDown={stopEventPropagation}
        onTouchStart={stopEventPropagation}
        style={{
          width: '100%',
          height: '100%',
          overflow: 'hidden',
          display: 'flex',
          flexDirection: 'column',
          boxSizing: 'border-box',
          background: theme.mainBg,
          fontFamily: 'Helvetica Neue, Calibri Light, Roboto, sans-serif',
          fontSize: '13px',
          color: theme.text,
        }}
      >
        <DevToolsTopRow
          close={close}
          hasProseMirrorMode={hasProseMirrorMode}
          mode={mode}
          version={version}
          plugins={plugins}
          contentState={contentState}
          selectedMode={selectedMode}
          onModeSelect={onModeSelect}
          canInspect={canInspect}
          isInspectActive={isInspectActive}
          onInspectToggle={toggleInspectMode}
        />
        <div
          style={{
            flex: 1,
            minHeight: 0,
            overflow: 'hidden',
          }}
        >
          <Tabs onSelect={setTabIndex} selectedIndex={tabIndex}>
            <TabList>
              <Tab index="state">State</Tab>
              <Tab index="contentEditor">Content Editor</Tab>
              <Tab index="props">All Props</Tab>
              <Tab index="schema">Schema</Tab>
              <Tab index="rendering">Rendering</Tab>
              {mode === 'editor' && <Tab index="networkConditions">Network conditions</Tab>}
              <Tab index="overrides">Overrides</Tab>
            </TabList>

            <TabPanel>
              {({ index }): React.ReactNode => {
                switch (index) {
                  case 'state':
                    return (
                      <RichContentTree content={contentState} selectedNodeId={selectedNodeId} />
                    );
                  case 'contentEditor':
                    return (
                      <RicosContentEditorTab
                        editorPlugins={plugins}
                        content={schema.getContent()}
                        onChange={content => schema.setContent(content)}
                        mode={mode}
                        selectedNodeId={selectedNodeId}
                      />
                    );
                  case 'props':
                    return <RicosPropsTab ricosProps={ricosProps} />;
                  case 'schema':
                    return <RicosSchemaTab />;
                  case 'rendering':
                    return <RicosRenderingTab />;
                  case 'networkConditions':
                    return mode === 'editor' ? <RicosNetworkConditionsTab /> : null;
                  case 'overrides':
                    return <OverridesTab />;
                  default:
                    return <div>unknown tab</div>;
                }
              }}
            </TabPanel>
          </Tabs>
        </div>
      </div>
    </Dock>,
    document.body
  );
};

const RicosProseMirrorOverlay: React.FC<{
  close: () => void;
  dockSize: number;
  onDockSizeChange: (size: number) => void;
  mode: Props['mode'];
  version: string;
  ricosProps: Props['ricosProps'];
  contentState: Props['contentState'];
  selectedMode: DevToolsMode;
  onModeSelect: (mode: DevToolsMode) => void;
  proseMirrorNodePickerButton: HTMLButtonElement | null;
  proseMirrorSaveSnapshotButton: HTMLButtonElement | null;
}> = ({
  close,
  dockSize,
  onDockSizeChange,
  mode,
  version,
  ricosProps,
  contentState,
  selectedMode,
  onModeSelect,
  proseMirrorNodePickerButton,
  proseMirrorSaveSnapshotButton,
}) => {
  const visibleDockSize = getVisibleProseMirrorDockSize(dockSize);
  const overlayTop = Math.max(12, window.innerHeight * (1 - visibleDockSize));
  const plugins = getEditorPluginNames(ricosProps.plugins);
  const activeResizeCleanupRef = React.useRef<(() => void) | null>(null);

  const startResize = React.useCallback(
    (startY: number) => {
      activeResizeCleanupRef.current?.();

      const initialDockSize = dockSize;

      const updateSize = (clientY: number) => {
        const nextSize = clampDockSize(initialDockSize + (startY - clientY) / window.innerHeight);
        onDockSizeChange(nextSize);
      };

      const handleMouseMove = (event: MouseEvent) => {
        event.preventDefault();
        updateSize(getPointerClientY(event));
      };
      const handleTouchMove = (event: TouchEvent) => {
        event.preventDefault();
        updateSize(getPointerClientY(event));
      };
      const stopResize = () => {
        activeResizeCleanupRef.current = null;
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        window.removeEventListener('mousemove', handleMouseMove);
        window.removeEventListener('mouseup', stopResize);
        window.removeEventListener('touchmove', handleTouchMove);
        window.removeEventListener('touchend', stopResize);
        window.removeEventListener('touchcancel', stopResize);
      };

      activeResizeCleanupRef.current = stopResize;
      document.body.style.cursor = 'row-resize';
      document.body.style.userSelect = 'none';
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', stopResize);
      window.addEventListener('touchmove', handleTouchMove, { passive: false });
      window.addEventListener('touchend', stopResize);
      window.addEventListener('touchcancel', stopResize);
    },
    [dockSize, onDockSizeChange]
  );

  const onResizeHandleMouseDown = React.useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      event.preventDefault();
      startResize(event.clientY);
    },
    [startResize]
  );

  const onResizeHandleTouchStart = React.useCallback(
    (event: React.TouchEvent<HTMLDivElement>) => {
      event.preventDefault();
      startResize(event.touches[0]?.clientY ?? 0);
    },
    [startResize]
  );

  React.useEffect(
    () => () => {
      activeResizeCleanupRef.current?.();
    },
    []
  );

  const handleProseMirrorInspectClick = React.useCallback(() => {
    proseMirrorNodePickerButton?.click();
  }, [proseMirrorNodePickerButton]);

  const handleProseMirrorSaveSnapshotClick = React.useCallback(() => {
    proseMirrorSaveSnapshotButton?.click();
  }, [proseMirrorSaveSnapshotButton]);

  return ReactDOM.createPortal(
    <div
      data-hook={CLICK_OUTSIDE_SAFE_DATA_HOOK}
      onMouseDown={stopEventPropagation}
      onTouchStart={stopEventPropagation}
      style={{
        position: 'fixed',
        top: `${overlayTop}px`,
        left: 0,
        width: '100%',
        zIndex: DEV_TOOLS_Z_INDEX + 1,
        display: 'flex',
        flexDirection: 'column',
        boxSizing: 'border-box',
        pointerEvents: 'auto',
        background: theme.mainBg,
        color: theme.text,
        fontFamily: 'Helvetica Neue, Calibri Light, Roboto, sans-serif',
        fontSize: '13px',
      }}
    >
      <DevToolsTopRow
        close={close}
        hasProseMirrorMode
        mode={mode}
        version={version}
        plugins={plugins}
        contentState={contentState}
        selectedMode={selectedMode}
        onModeSelect={onModeSelect}
        onResizeMouseDown={onResizeHandleMouseDown}
        onResizeTouchStart={onResizeHandleTouchStart}
        extraControls={
          <>
            {proseMirrorSaveSnapshotButton ? (
              <ProseMirrorSaveSnapshotButton onClick={handleProseMirrorSaveSnapshotClick} />
            ) : null}
            {proseMirrorNodePickerButton ? (
              <ProseMirrorInspectButton onClick={handleProseMirrorInspectClick} />
            ) : null}
          </>
        }
      />
    </div>,
    document.body
  );
};

const DevToolsTopRow: React.FC<{
  close: () => void;
  hasProseMirrorMode: boolean;
  mode: Props['mode'];
  version: string;
  plugins: string[];
  contentState: Props['contentState'];
  selectedMode: DevToolsMode;
  onModeSelect: (mode: DevToolsMode) => void;
  onResizeMouseDown?: React.MouseEventHandler<HTMLDivElement>;
  onResizeTouchStart?: React.TouchEventHandler<HTMLDivElement>;
  canInspect?: boolean;
  isInspectActive?: boolean;
  onInspectToggle?: () => void;
  extraControls?: React.ReactNode;
}> = ({
  close,
  hasProseMirrorMode,
  mode,
  version,
  plugins,
  contentState,
  selectedMode,
  onModeSelect,
  onResizeMouseDown,
  onResizeTouchStart,
  canInspect,
  isInspectActive,
  onInspectToggle,
  extraControls,
}) => {
  const encodedContent = encodeUnicodeBase64(JSON.stringify(contentState));
  const isResizable = Boolean(onResizeMouseDown || onResizeTouchStart);
  const openInRicosDevHref = `https://ricos.dev?v=${version}&plugins=${
    plugins.length ? plugins.join('.') : 'NONE'
  }#content=${encodedContent}`;

  const handleMouseDown = React.useCallback(
    (event: React.MouseEvent<HTMLDivElement>) => {
      if (!onResizeMouseDown || isInteractiveTarget(event.target)) {
        return;
      }

      onResizeMouseDown(event);
    },
    [onResizeMouseDown]
  );

  const handleTouchStart = React.useCallback(
    (event: React.TouchEvent<HTMLDivElement>) => {
      if (!onResizeTouchStart || isInteractiveTarget(event.target)) {
        return;
      }

      onResizeTouchStart(event);
    },
    [onResizeTouchStart]
  );

  return (
    <div
      onMouseDown={handleMouseDown}
      onTouchStart={handleTouchStart}
      style={{
        width: '100%',
        display: 'flex',
        alignItems: 'center',
        background: theme.mainBg,
        color: theme.text,
        boxSizing: 'border-box',
        borderBottom: `1px solid ${theme.main20}`,
        minHeight: `${SHELL_TOP_ROW_HEIGHT}px`,
        justifyContent: 'space-between',
        gap: '12px',
        padding: '0 8px',
        cursor: isResizable ? 'row-resize' : undefined,
      }}
    >
      <div style={{ display: 'flex', alignItems: 'center', minWidth: 0 }}>
        {hasProseMirrorMode ? (
          <div
            style={{
              display: 'inline-flex',
              alignItems: 'center',
              gap: '4px',
              padding: '2px',
              borderRadius: '999px',
              background: theme.white05,
            }}
          >
            <button
              type="button"
              onClick={() => onModeSelect('ricos')}
              style={{
                border: 'none',
                borderRadius: '999px',
                background: selectedMode === 'ricos' ? theme.main20 : 'transparent',
                color: selectedMode === 'ricos' ? theme.white : theme.white60,
                cursor: 'pointer',
                fontSize: '12px',
                fontWeight: 600,
                lineHeight: 1,
                padding: '6px 12px',
                transition: 'background .2s ease, color .2s ease',
              }}
            >
              Ricos
            </button>
            <button
              type="button"
              onClick={() => onModeSelect('prosemirror')}
              style={{
                border: 'none',
                borderRadius: '999px',
                background: selectedMode === 'prosemirror' ? theme.main20 : 'transparent',
                color: selectedMode === 'prosemirror' ? theme.white : theme.white60,
                cursor: 'pointer',
                fontSize: '12px',
                fontWeight: 600,
                lineHeight: 1,
                padding: '6px 12px',
                transition: 'background .2s ease, color .2s ease',
              }}
            >
              ProseMirror
            </button>
          </div>
        ) : null}
      </div>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'flex-end',
          gap: '12px',
          marginLeft: 'auto',
          minWidth: 0,
        }}
      >
        {canInspect && onInspectToggle ? (
          <RicosInspectButton isActive={Boolean(isInspectActive)} onClick={onInspectToggle} />
        ) : null}
        {extraControls}
        <span
          style={{
            color: theme.white60,
            fontSize: '12px',
            letterSpacing: '0.02em',
            whiteSpace: 'nowrap',
          }}
        >
          {mode === 'editor' ? `ricos-editor@${version}` : `ricos-viewer@${version}`}
          {hasWixInsiderOverride && (
            <>
              {' '}
              <span style={{ color: 'red' }}>{getOverrideValue()}</span>
            </>
          )}
        </span>
        <a
          style={{
            color: theme.white80,
            fontSize: '12px',
            textDecoration: 'none',
          }}
          href={openInRicosDevHref}
          target="_blank"
          rel="noreferrer"
        >
          Open in RICOS.DEV
        </a>
        <button
          type="button"
          onClick={close}
          style={{
            background: 'transparent',
            border: 'none',
            color: theme.white60,
            cursor: 'pointer',
            fontSize: '18px',
            lineHeight: 1,
            padding: '0 2px',
          }}
        >
          ×
        </button>
      </div>
    </div>
  );
};

const RicosInspectButton: React.FC<{
  isActive: boolean;
  onClick: () => void;
}> = ({ isActive, onClick }) => (
  <button
    type="button"
    aria-label="Inspect rich content node"
    aria-pressed={isActive}
    title="Inspect rich content node"
    onClick={onClick}
    style={{
      appearance: 'none',
      width: '24px',
      height: '24px',
      border: 'none',
      borderRadius: '3px',
      cursor: 'pointer',
      flex: '0 0 auto',
      backgroundColor: isActive
        ? RICOS_INSPECT_BUTTON_ACTIVE_BACKGROUND
        : RICOS_INSPECT_BUTTON_BACKGROUND,
      backgroundImage: `url("${RICOS_INSPECT_TRIGGER_ICON}")`,
      backgroundSize: '20px 20px',
      backgroundRepeat: 'no-repeat',
      backgroundPosition: '50% 50%',
      transition: 'background-color .2s ease, transform .2s ease',
    }}
  />
);

const ProseMirrorInspectButton: React.FC<{
  onClick: () => void;
}> = ({ onClick }) => (
  <button
    type="button"
    aria-label="Inspect ProseMirror node"
    title="Inspect ProseMirror node"
    onClick={onClick}
    style={{
      appearance: 'none',
      width: '24px',
      height: '24px',
      border: 'none',
      borderRadius: '3px',
      cursor: 'pointer',
      flex: '0 0 auto',
      backgroundColor: PROSEMIRROR_TOOL_BUTTON_BACKGROUND,
      backgroundImage: `url("${RICOS_INSPECT_TRIGGER_ICON}")`,
      backgroundSize: '20px 20px',
      backgroundRepeat: 'no-repeat',
      backgroundPosition: '50% 50%',
      transition: 'background-color .2s ease',
    }}
  />
);

const ProseMirrorSaveSnapshotButton: React.FC<{
  onClick: () => void;
}> = ({ onClick }) => (
  <button
    type="button"
    onClick={onClick}
    style={{
      appearance: 'none',
      border: 'none',
      borderRadius: '3px',
      background: PROSEMIRROR_TOOL_BUTTON_BACKGROUND,
      color: theme.white,
      cursor: 'pointer',
      fontSize: '12px',
      lineHeight: '24px',
      height: '24px',
      padding: '0 6px',
      transition: 'background-color .2s ease',
      flex: '0 0 auto',
    }}
  >
    Save snapshots
  </button>
);

// oxlint-disable-next-line import/no-default-export
export default RicosDevTools;
