import type { EditorView } from './../../tiptap/pm/view.js';

const ROOT_CLASS_NAME = '__prosemirror-dev-tools__';
const COLLAPSED_BUTTON_SELECTOR = '[data-test-id="__prosemirror_devtools_collapsed_button__"]';
const CONTAINER_SELECTOR = '[data-test-id="__prosemirror_devtools_container__"]';
const CLOSE_BUTTON_SELECTOR = '[data-test-id="__prosemirror_devtools_close_button__"]';
export const CLICK_OUTSIDE_SAFE_DATA_HOOK = 'mock-modal';
export const DEV_TOOLS_Z_INDEX = 10000;
const DEFAULT_DOCK_SIZE = 0.5;
const MIN_DOCK_SIZE = 0.15;
const MAX_DOCK_SIZE = 0.95;
const STOP_PROPAGATION_EVENT_NAMES = ['mousedown', 'touchstart'] as const;

type ProseMirrorDevToolsElements = {
  root: HTMLDivElement | null;
  dockWrapper: HTMLDivElement | null;
  dock: HTMLDivElement | null;
  container: HTMLDivElement | null;
  collapsedButton: HTMLButtonElement | null;
  closeButton: HTMLButtonElement | null;
  floatingButtons: HTMLButtonElement[];
  nodePickerButton: HTMLButtonElement | null;
  saveSnapshotButton: HTMLButtonElement | null;
};

type ProseMirrorDevToolsState = {
  cleanup?: () => void;
  currentEditorView?: EditorView;
  htmlMarginBottomBeforeOverride?: string;
  mountRequestId?: number;
  mountPromise?: Promise<ProseMirrorDevToolsElements | null>;
  guardedRoot?: HTMLDivElement;
  eventGuardsCleanup?: () => void;
};

declare global {
  interface Window {
    __RICOS_PROSEMIRROR_DEV_TOOLS__?: ProseMirrorDevToolsState;
  }
}

const getGlobalState = (): ProseMirrorDevToolsState => {
  window.__RICOS_PROSEMIRROR_DEV_TOOLS__ =
    window.__RICOS_PROSEMIRROR_DEV_TOOLS__ ?? ({} as ProseMirrorDevToolsState);

  return window.__RICOS_PROSEMIRROR_DEV_TOOLS__;
};

const getRoot = (): HTMLDivElement | null =>
  document.querySelector<HTMLDivElement>(`.${ROOT_CLASS_NAME}`);

export const getProseMirrorDevToolsElements = (): ProseMirrorDevToolsElements => {
  const root = getRoot();
  const container = root?.querySelector<HTMLDivElement>(CONTAINER_SELECTOR) ?? null;
  const collapsedButton = root?.querySelector<HTMLButtonElement>(COLLAPSED_BUTTON_SELECTOR) ?? null;
  const closeButton = root?.querySelector<HTMLButtonElement>(CLOSE_BUTTON_SELECTOR) ?? null;
  const dock =
    container?.parentElement?.parentElement instanceof HTMLDivElement
      ? container.parentElement.parentElement
      : null;
  const dockWrapper = dock?.parentElement instanceof HTMLDivElement ? dock.parentElement : null;
  const floatingButtons = Array.from(
    root?.querySelectorAll<HTMLButtonElement>('button') ?? []
  ).filter(
    button =>
      button !== collapsedButton && button !== closeButton && button.parentElement === container
  );
  const saveSnapshotButton =
    floatingButtons.find(button => Boolean(button.textContent?.trim().length)) ?? null;
  const nodePickerButton = floatingButtons.find(button => button !== saveSnapshotButton) ?? null;

  return {
    root,
    dockWrapper,
    dock,
    container,
    collapsedButton,
    closeButton,
    floatingButtons,
    nodePickerButton,
    saveSnapshotButton,
  };
};

const waitForDevToolsElements = (
  predicate: (elements: ProseMirrorDevToolsElements) => boolean,
  timeout = 1500
): Promise<ProseMirrorDevToolsElements> => {
  const existing = getProseMirrorDevToolsElements();
  if (predicate(existing)) {
    return Promise.resolve(existing);
  }

  return new Promise((resolve, reject) => {
    const observer = new MutationObserver(() => {
      const elements = getProseMirrorDevToolsElements();
      if (predicate(elements)) {
        observer.disconnect();
        clearTimeout(timeoutId);
        resolve(elements);
      }
    });

    const timeoutId = window.setTimeout(() => {
      observer.disconnect();
      reject(new Error('Timed out while waiting for ProseMirror devtools'));
    }, timeout);

    observer.observe(document.body, {
      attributes: true,
      childList: true,
      subtree: true,
    });
  });
};

const setCollapsedButtonVisibility = (
  elements: Pick<ProseMirrorDevToolsElements, 'collapsedButton'>,
  isVisible: boolean
) => {
  if (elements.collapsedButton) {
    elements.collapsedButton.style.display = isVisible ? '' : 'none';
  }
};

const setCloseButtonVisibility = (
  elements: Pick<ProseMirrorDevToolsElements, 'closeButton'>,
  isVisible: boolean
) => {
  if (elements.closeButton) {
    elements.closeButton.style.display = isVisible ? '' : 'none';
  }
};

const clampDockSize = (size: number) => Math.min(MAX_DOCK_SIZE, Math.max(MIN_DOCK_SIZE, size));

const getReservedHeight = (size: number) => clampDockSize(size) * window.innerHeight;

const captureHtmlMarginBottomBeforeOverride = () => {
  const state = getGlobalState();

  if (typeof state.htmlMarginBottomBeforeOverride === 'undefined') {
    state.htmlMarginBottomBeforeOverride = document.documentElement.style.marginBottom;
  }
};

export const setDevToolsHtmlMarginBottomPixels = (height?: number) => {
  const state = getGlobalState();

  if (typeof height === 'number') {
    captureHtmlMarginBottomBeforeOverride();
    document.documentElement.style.marginBottom = `${height}px`;
    return;
  }

  if (typeof state.htmlMarginBottomBeforeOverride !== 'undefined') {
    document.documentElement.style.marginBottom = state.htmlMarginBottomBeforeOverride;
    state.htmlMarginBottomBeforeOverride = undefined;
  }
};

const setHtmlMarginBottom = (size?: number) => {
  setDevToolsHtmlMarginBottomPixels(typeof size === 'number' ? getReservedHeight(size) : undefined);
};

const setRootVisibility = (
  elements: Pick<ProseMirrorDevToolsElements, 'root'>,
  isVisible: boolean
) => {
  if (!elements.root) {
    return;
  }

  elements.root.style.display = isVisible ? '' : 'none';
  elements.root.style.pointerEvents = isVisible ? '' : 'none';
};

const stopEventPropagation = (event: Event) => {
  event.stopPropagation();
};

const syncStandaloneProseMirrorDevToolsWrapper = (elements: ProseMirrorDevToolsElements) => {
  const state = getGlobalState();

  elements.root?.setAttribute('data-hook', CLICK_OUTSIDE_SAFE_DATA_HOOK);

  if (elements.dockWrapper) {
    elements.dockWrapper.style.zIndex = `${DEV_TOOLS_Z_INDEX}`;
  }

  if (state.guardedRoot === elements.root) {
    return;
  }

  state.eventGuardsCleanup?.();
  state.guardedRoot = elements.root ?? undefined;

  if (!elements.root) {
    state.eventGuardsCleanup = undefined;
    return;
  }

  STOP_PROPAGATION_EVENT_NAMES.forEach(eventName => {
    elements.root?.addEventListener(eventName, stopEventPropagation);
  });

  state.eventGuardsCleanup = () => {
    STOP_PROPAGATION_EVENT_NAMES.forEach(eventName => {
      elements.root?.removeEventListener(eventName, stopEventPropagation);
    });

    if (state.guardedRoot === elements.root) {
      state.guardedRoot = undefined;
    }

    state.eventGuardsCleanup = undefined;
  };
};

export const setProseMirrorFloatingControlsOffset = (offsetTop?: number) => {
  const elements = getProseMirrorDevToolsElements();

  elements.floatingButtons.forEach(button => {
    button.style.top = typeof offsetTop === 'number' ? `${offsetTop}px` : '';
  });
};

export const setProseMirrorFloatingControlsVisibility = (isVisible: boolean) => {
  const elements = getProseMirrorDevToolsElements();

  elements.floatingButtons.forEach(button => {
    button.style.display = isVisible ? '' : 'none';
  });
};

export const setProseMirrorDevToolsSize = (
  size: number,
  reservedHeight = getReservedHeight(size)
) => {
  const nextSize = clampDockSize(size);
  const elements = getProseMirrorDevToolsElements();

  if (elements.dock) {
    const dockHeight = nextSize * window.innerHeight;
    elements.dock.style.top = `${window.innerHeight - dockHeight}px`;
    elements.dock.style.height = `${dockHeight}px`;
  }

  if (elements.root?.style.display !== 'none') {
    setDevToolsHtmlMarginBottomPixels(reservedHeight);
  }
};

const mountStandaloneProseMirrorDevTools = async (
  editorView: EditorView
): Promise<ProseMirrorDevToolsElements | null> => {
  if (typeof window === 'undefined') {
    return null;
  }

  const state = getGlobalState();
  const existing = getProseMirrorDevToolsElements();

  if (state.currentEditorView === editorView && existing.root) {
    setCollapsedButtonVisibility(existing, false);
    setCloseButtonVisibility(existing, false);
    setRootVisibility(existing, false);
    setHtmlMarginBottom();
    syncStandaloneProseMirrorDevToolsWrapper(existing);
    return existing;
  }

  if (state.mountPromise && state.currentEditorView === editorView) {
    return state.mountPromise;
  }

  const requestId = (state.mountRequestId ?? 0) + 1;
  state.mountRequestId = requestId;
  state.currentEditorView = editorView;
  state.mountPromise = import(
    /* webpackChunkName: "ricos_prosemirror-dev-tools" */
    'prosemirror-dev-tools'
  )
    .then(({ applyDevTools }) => {
      if (state.currentEditorView !== editorView || state.mountRequestId !== requestId) {
        return getProseMirrorDevToolsElements();
      }

      state.cleanup?.();
      state.cleanup = applyDevTools(editorView, {});

      return waitForDevToolsElements(elements => Boolean(elements.root)).then(elements => {
        if (state.mountRequestId === requestId) {
          state.mountPromise = undefined;
        }

        if (state.currentEditorView !== editorView || state.mountRequestId !== requestId) {
          return getProseMirrorDevToolsElements();
        }

        setCollapsedButtonVisibility(elements, false);
        setCloseButtonVisibility(elements, false);
        setRootVisibility(elements, false);
        setProseMirrorFloatingControlsOffset();
        setHtmlMarginBottom();
        syncStandaloneProseMirrorDevToolsWrapper(elements);
        return elements;
      });
    })
    .catch(error => {
      if (state.mountRequestId === requestId) {
        state.mountPromise = undefined;
      }

      console.error('Failed to load prosemirror-dev-tools', error);
      return null;
    });

  return state.mountPromise;
};

export const showStandaloneProseMirrorDevTools = async (
  editorView: EditorView,
  preferredSize = DEFAULT_DOCK_SIZE,
  reservedHeight = getReservedHeight(preferredSize)
): Promise<ProseMirrorDevToolsElements | null> => {
  const mountedElements = await mountStandaloneProseMirrorDevTools(editorView);
  if (!mountedElements) {
    return null;
  }

  let elements = getProseMirrorDevToolsElements();
  if (!elements.container) {
    captureHtmlMarginBottomBeforeOverride();
    setCollapsedButtonVisibility(elements, true);
    elements.collapsedButton?.click();
    try {
      elements = await waitForDevToolsElements(nextElements => Boolean(nextElements.container));
    } catch (error) {
      console.error('Failed to open prosemirror-dev-tools', error);
      return getProseMirrorDevToolsElements();
    }
  }

  setCollapsedButtonVisibility(elements, false);
  setCloseButtonVisibility(elements, false);
  setRootVisibility(elements, true);
  setProseMirrorDevToolsSize(preferredSize, reservedHeight);
  setProseMirrorFloatingControlsOffset();
  setDevToolsHtmlMarginBottomPixels(reservedHeight);
  syncStandaloneProseMirrorDevToolsWrapper(elements);

  return elements;
};

export const hideStandaloneProseMirrorDevTools = (
  preservedReservedHeight?: number
): ProseMirrorDevToolsElements | null => {
  if (typeof window === 'undefined') {
    return null;
  }

  const elements = getProseMirrorDevToolsElements();
  if (!elements.root) {
    return null;
  }

  if (elements.container && typeof preservedReservedHeight !== 'number') {
    setCloseButtonVisibility(elements, true);
    elements.closeButton?.click();
  }

  const nextElements = getProseMirrorDevToolsElements();
  setRootVisibility(nextElements, false);
  setDevToolsHtmlMarginBottomPixels(preservedReservedHeight);
  setCollapsedButtonVisibility(nextElements, false);
  setCloseButtonVisibility(nextElements, false);
  setProseMirrorFloatingControlsOffset();
  setProseMirrorFloatingControlsVisibility(true);

  return nextElements;
};
