/* oxlint-disable no-console */
import React from 'react';
import { JSONTree } from 'react-json-tree';

import type { ValidationError } from './../../../ricos-schema/next-schema/index.js';
import { validateRicosDocument } from './../../../ricos-schema/next-schema/index.js';

import { Button } from '../components/button.js';
import { jsonTreeTheme, mainTheme as theme } from '../theme.js';

type Props = {
  content: any;
  selectedNodeId?: string;
};

type TreePath = (string | number)[];

export const RichContentTree: React.FC<Props> = ({ content, selectedNodeId }) => {
  const errors = React.useMemo(() => {
    const validationResult = validateRicosDocument(content);
    return validationResult.type === 'ok' ? [] : validationResult.errors;
  }, [content]);
  const containerRef = React.useRef<HTMLDivElement>(null);
  const hasErrorUnder = isErrorUnderNode(errors);
  const getErrorFor = getErrorForNode(errors);
  const selectedTreePath = React.useMemo(() => {
    if (!selectedNodeId) {
      return undefined;
    }

    return findTreePathByNodeId(content, selectedNodeId);
  }, [content, selectedNodeId]);

  const isSelectedPath = React.useCallback(
    (nodePath: TreePath) => {
      if (!selectedTreePath) {
        return false;
      }

      const normalizedNodePath = [...nodePath].reverse();
      return (
        normalizedNodePath.length === selectedTreePath.length &&
        normalizedNodePath.every((pathSegment, index) => pathSegment === selectedTreePath[index])
      );
    },
    [selectedTreePath]
  );

  const isSelectionUnderNode = React.useCallback(
    (nodePath: TreePath) => {
      if (!selectedTreePath) {
        return false;
      }

      const normalizedNodePath = [...nodePath].reverse();
      return normalizedNodePath.every(
        (pathSegment, index) => pathSegment === selectedTreePath[index]
      );
    },
    [selectedTreePath]
  );

  React.useEffect(() => {
    if (!selectedNodeId || !containerRef.current) {
      return;
    }

    const frameId = window.requestAnimationFrame(() => {
      containerRef.current
        ?.querySelector<HTMLElement>('[data-selected-tree-node="true"]')
        ?.scrollIntoView({
          block: 'center',
        });
    });

    return () => {
      window.cancelAnimationFrame(frameId);
    };
  }, [selectedNodeId, selectedTreePath]);

  return (
    <div ref={containerRef}>
      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        {errors.length ? (
          <Button
            style={{ border: '1px solid red', marginRight: '10px' }}
            onClick={() => {
              console.log(errors);
            }}
          >
            Log Errors
          </Button>
        ) : null}
        <Button
          onClick={() => {
            navigator.clipboard.writeText(JSON.stringify(content));
          }}
          style={{ marginRight: '10px' }}
        >
          Copy into clipboard
        </Button>
        <Button
          onClick={() => {
            // oxlint-disable-next-line no-console
            console.log(content);
          }}
        >
          Log to console
        </Button>
      </div>
      <JSONTree
        valueRenderer={(valueAsString, _value, ...nodePath) => {
          const error = getErrorFor(nodePath);
          if (error) {
            return (
              <span style={getTreeNodeStyles(isSelectedPath(nodePath), { color: 'red' })}>
                {valueAsString} [Error: {error.message}]
              </span>
            );
          }

          return <span style={getTreeNodeStyles(isSelectedPath(nodePath))}>{valueAsString}</span>;
        }}
        getItemString={(type, value, defaultView, keysCount, nodePath) => {
          const error = getErrorFor(nodePath);
          const hasError = hasErrorUnder(nodePath);
          const isSelected = isSelectedPath(nodePath);
          if (error) {
            return (
              <span style={getTreeNodeStyles(isSelected)}>
                {defaultView} {keysCount} <span style={{ color: 'red' }}>{error.message}</span>
              </span>
            );
          }
          if (type === 'Object' && value.type) {
            return (
              <span style={getTreeNodeStyles(isSelected, hasError ? { color: 'red' } : undefined)}>
                {'{} '}
                {value.type}
              </span>
            );
          }

          return (
            <span style={getTreeNodeStyles(isSelected, hasError ? { color: 'red' } : undefined)}>
              {defaultView} {keysCount}
            </span>
          );
        }}
        labelRenderer={(nodePath, _nodeType, _expanded, _expandable) => {
          const [label] = nodePath;
          const isSelected = isSelectedPath(nodePath);
          return (
            <span
              data-selected-tree-node={isSelected ? 'true' : undefined}
              style={getTreeNodeStyles(isSelected)}
            >
              {label}:
            </span>
          );
        }}
        data={content}
        invertTheme={false}
        theme={jsonTreeTheme}
        hideRoot
        shouldExpandNode={nodePath => hasErrorUnder(nodePath) || isSelectionUnderNode(nodePath)}
      />
    </div>
  );
};

const getTreeNodeStyles = (isSelected: boolean, style?: React.CSSProperties) => {
  if (!isSelected) {
    return style;
  }

  return {
    ...style,
    background: 'rgba(137, 220, 235, .18)',
    color: theme.white,
    borderRadius: '3px',
    padding: '1px 4px',
  };
};

const getErrorForNode =
  (errors: ValidationError[]) =>
  (nodePath: (string | number)[]): ValidationError | undefined => {
    if (!errors.length) {
      return;
    }
    const nodePathAsPointer = [...nodePath].reverse().map(p => p.toString());
    return errors.find(({ instancePath }) => {
      return (
        instancePath.length === nodePathAsPointer.length &&
        instancePath.every((p, i) => p === nodePathAsPointer[i])
      );
    });
  };

const findTreePathByNodeId = (
  value: unknown,
  selectedNodeId: string,
  currentPath: TreePath = []
): TreePath | undefined => {
  if (!value || typeof value !== 'object') {
    return undefined;
  }

  const objectValue = value as Record<string, unknown>;

  if (
    !Array.isArray(value) &&
    typeof objectValue.id === 'string' &&
    objectValue.id === selectedNodeId &&
    typeof objectValue.type === 'string'
  ) {
    return currentPath;
  }

  if (Array.isArray(value)) {
    for (const [index, child] of value.entries()) {
      const nestedPath = findTreePathByNodeId(child, selectedNodeId, [...currentPath, index]);
      if (nestedPath) {
        return nestedPath;
      }
    }
    return undefined;
  }

  for (const [key, child] of Object.entries(value)) {
    const nestedPath = findTreePathByNodeId(child, selectedNodeId, [...currentPath, key]);
    if (nestedPath) {
      return nestedPath;
    }
  }

  return undefined;
};

const isErrorUnderNode =
  (errors: ValidationError[]) =>
  (nodePath: (string | number)[]): boolean => {
    if (!errors.length) {
      return false;
    }
    const nodePathAsPointer = [...nodePath].reverse().map(p => p.toString());
    return !!errors.find(({ instancePath }) => {
      return nodePathAsPointer.every((p, i) => instancePath[i] === p);
    });
  };
