import React from 'react';

const buttonHoverStyle = `.ricos-dev-tools-button:hover:not(:disabled) {
  background-color: rgba(203, 166, 247, .4);
  color: #cdd6f4;
}
.ricos-dev-tools-button:disabled,
.ricos-dev-tools-button[aria-disabled='true'] {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}`;

const buttonStyle: React.CSSProperties = {
  border: 'none',
  textTransform: 'uppercase',
  fontWeight: 400,
  letterSpacing: '1px',
  padding: '6px 10px',
  margin: '0 0 0 8px',
  fontSize: '11px',
  color: 'rgba(205, 214, 244, .8)',
  transition: 'background .3s, color .3s, opacity .15s',
  borderRadius: '2px',
  background: 'transparent',
  cursor: 'pointer',
  textDecoration: 'none',
  display: 'inline-block',
};

type ButtonProps = React.ButtonHTMLAttributes<HTMLButtonElement>;
type AnchorButtonProps = Omit<React.AnchorHTMLAttributes<HTMLAnchorElement>, 'disabled'> & {
  href: string;
  disabled?: boolean;
};

// When `href` is provided, renders an <a> so plain-click does same-tab
// navigation and Cmd/Shift/middle-click open a new tab natively. Otherwise
// renders a <button>.
export const Button: React.FC<ButtonProps | AnchorButtonProps> = props => {
  if ('href' in props) {
    const { href, disabled, ...rest } = props;
    return (
      <>
        <style>{buttonHoverStyle}</style>
        <a
          {...rest}
          href={disabled ? undefined : href}
          aria-disabled={disabled || undefined}
          style={buttonStyle}
          className="ricos-dev-tools-button"
        />
      </>
    );
  }

  return (
    <>
      <style>{buttonHoverStyle}</style>
      <button type="button" {...props} style={buttonStyle} className="ricos-dev-tools-button" />
    </>
  );
};
